import csv
import math
from datetime import datetime
from collections import defaultdict
import json

# ──────────────────────────────────────────────
# 1.  Read and parse data
# ──────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", newline="") as f:
    reader = csv.DictReader(f)
    for r in reader:
        dt = datetime.strptime(r["Date"], "%m/%d/%Y")
        rows.append({
            "date": dt,
            "close": float(r["Close"]),
            "high": float(r["High"]),
            "low": float(r["Low"]),
            "open": float(r["Open"]),
            "volume": int(r["Volume"]),
        })

rows.sort(key=lambda x: x["date"])

# ──────────────────────────────────────────────
# 2.  Compute KPIs
# ──────────────────────────────────────────────
first_close = rows[0]["close"]
last_close = rows[-1]["close"]
first_date = rows[0]["date"]
last_date = rows[-1]["date"]
n_days = len(rows)

cumulative_return = (last_close / first_close - 1) * 100
years = (last_date - first_date).days / 365.25
cagr = ((last_close / first_close) ** (1 / years) - 1) * 100

# Daily returns
daily_returns = []
for i in range(1, len(rows)):
    daily_returns.append(rows[i]["close"] / rows[i - 1]["close"] - 1)

avg_daily_vol = sum(r["volume"] for r in rows) / n_days

# Annualized volatility
mean_ret = sum(daily_returns) / len(daily_returns)
var_ret = sum((r - mean_ret) ** 2 for r in daily_returns) / (len(daily_returns) - 1)
daily_std = math.sqrt(var_ret)
ann_volatility = daily_std * math.sqrt(252) * 100

# Maximum drawdown
peak = rows[0]["close"]
max_dd = 0
max_dd_peak_date = rows[0]["date"]
max_dd_trough_date = rows[0]["date"]
current_peak_date = rows[0]["date"]
for r in rows:
    if r["close"] > peak:
        peak = r["close"]
        current_peak_date = r["date"]
    dd = (r["close"] / peak - 1) * 100
    if dd < max_dd:
        max_dd = dd
        max_dd_peak_date = current_peak_date
        max_dd_trough_date = r["date"]

# All-time high / low
ath_row = max(rows, key=lambda x: x["close"])
atl_row = min(rows, key=lambda x: x["close"])

# ──────────────────────────────────────────────
# 3.  Annual performance
# ──────────────────────────────────────────────
years_data = defaultdict(list)
for r in rows:
    years_data[r["date"].year].append(r)

annual_perf = []
for yr in sorted(years_data.keys()):
    yr_rows = years_data[yr]
    yr_open = yr_rows[0]["close"]
    yr_close_val = yr_rows[-1]["close"]
    yr_return = (yr_close_val / yr_open - 1) * 100
    yr_high = max(x["high"] for x in yr_rows)
    yr_low = min(x["low"] for x in yr_rows)
    yr_avg_vol = sum(x["volume"] for x in yr_rows) / len(yr_rows)

    # yearly volatility
    yr_daily_rets = []
    for i in range(1, len(yr_rows)):
        yr_daily_rets.append(yr_rows[i]["close"] / yr_rows[i-1]["close"] - 1)
    if len(yr_daily_rets) > 1:
        yr_mean = sum(yr_daily_rets) / len(yr_daily_rets)
        yr_var = sum((x - yr_mean)**2 for x in yr_daily_rets) / (len(yr_daily_rets) - 1)
        yr_vol = math.sqrt(yr_var) * math.sqrt(252) * 100
    else:
        yr_vol = 0

    annual_perf.append({
        "year": yr,
        "open": yr_open,
        "close": yr_close_val,
        "return": yr_return,
        "high": yr_high,
        "low": yr_low,
        "avg_vol": yr_avg_vol,
        "volatility": yr_vol,
    })

best_year = max(annual_perf, key=lambda x: x["return"])
worst_year = min(annual_perf, key=lambda x: x["return"])

# Decade performance
decade_perf = {}
for dec_start in [2000, 2010, 2020]:
    dec_end = dec_start + 9
    dec_rows = [r for r in rows if dec_start <= r["date"].year <= dec_end]
    if dec_rows:
        d_open = dec_rows[0]["close"]
        d_close = dec_rows[-1]["close"]
        d_years = (dec_rows[-1]["date"] - dec_rows[0]["date"]).days / 365.25
        d_return = (d_close / d_open - 1) * 100
        d_cagr = ((d_close / d_open) ** (1 / d_years) - 1) * 100 if d_years > 0 else 0
        decade_perf[f"{dec_start}s"] = {
            "total_return": d_return,
            "cagr": d_cagr,
            "start_price": d_open,
            "end_price": d_close
        }
# 2020s partial
dec_rows_20s = [r for r in rows if 2020 <= r["date"].year]
if dec_rows_20s:
    d_open = dec_rows_20s[0]["close"]
    d_close = dec_rows_20s[-1]["close"]
    d_years = (dec_rows_20s[-1]["date"] - dec_rows_20s[0]["date"]).days / 365.25
    d_return = (d_close / d_open - 1) * 100
    d_cagr = ((d_close / d_open) ** (1 / max(d_years, 0.01)) - 1) * 100
    decade_perf["2020s*"] = {
        "total_return": d_return,
        "cagr": d_cagr,
        "start_price": d_open,
        "end_price": d_close
    }

# ──────────────────────────────────────────────
# 4.  Rolling volatility (30-day)
# ──────────────────────────────────────────────
rolling_vol_dates = []
rolling_vol_vals = []
for i in range(30, len(rows)):
    window_rets = []
    for j in range(i - 29, i + 1):
        if j > 0:
            window_rets.append(rows[j]["close"] / rows[j-1]["close"] - 1)
    if len(window_rets) > 1:
        w_mean = sum(window_rets) / len(window_rets)
        w_var = sum((x - w_mean)**2 for x in window_rets) / (len(window_rets) - 1)
        rolling_vol_dates.append(rows[i]["date"].strftime("%Y-%m-%d"))
        rolling_vol_vals.append(round(math.sqrt(w_var) * math.sqrt(252) * 100, 2))

# ──────────────────────────────────────────────
# 5.  Monthly close for the main chart (reduce data points)
# ──────────────────────────────────────────────
monthly = defaultdict(list)
for r in rows:
    key = r["date"].strftime("%Y-%m")
    monthly[key].append(r)

monthly_dates = []
monthly_closes = []
monthly_volumes = []
monthly_highs = []
monthly_lows = []
for key in sorted(monthly.keys()):
    m_rows = monthly[key]
    monthly_dates.append(m_rows[-1]["date"].strftime("%Y-%m-%d"))
    monthly_closes.append(round(m_rows[-1]["close"], 2))
    monthly_volumes.append(round(sum(x["volume"] for x in m_rows) / len(m_rows)))
    monthly_highs.append(round(max(x["high"] for x in m_rows), 2))
    monthly_lows.append(round(min(x["low"] for x in m_rows), 2))

# Subsample rolling vol to monthly
rv_monthly_dates = []
rv_monthly_vals = []
rv_lookup = dict(zip(rolling_vol_dates, rolling_vol_vals))
for d in monthly_dates:
    if d in rv_lookup:
        rv_monthly_dates.append(d)
        rv_monthly_vals.append(rv_lookup[d])
    else:
        # find closest
        closest = min(rolling_vol_dates, key=lambda x: abs(datetime.strptime(x, "%Y-%m-%d") - datetime.strptime(d, "%Y-%m-%d")))
        rv_monthly_dates.append(d)
        rv_monthly_vals.append(rv_lookup[closest])

# ──────────────────────────────────────────────
# 6.  Identify key events / phases
# ──────────────────────────────────────────────
# Major drawdown periods (>20%)
drawdowns = []
peak_price = rows[0]["close"]
peak_dt = rows[0]["date"]
in_drawdown = False
dd_start = None
dd_trough = None
dd_trough_price = None

for r in rows:
    if r["close"] > peak_price:
        if in_drawdown and dd_trough is not None:
            dd_pct = (dd_trough_price / peak_price - 1) * 100
            if dd_pct < -20:
                drawdowns.append({
                    "peak_date": peak_dt.strftime("%b %Y"),
                    "trough_date": dd_trough.strftime("%b %Y"),
                    "drawdown": round(dd_pct, 1),
                    "peak_price": round(peak_price, 2),
                    "trough_price": round(dd_trough_price, 2),
                })
            in_drawdown = False
        peak_price = r["close"]
        peak_dt = r["date"]
        dd_trough = None
        dd_trough_price = None
    else:
        dd = (r["close"] / peak_price - 1) * 100
        if dd < -10:
            in_drawdown = True
        if dd_trough_price is None or r["close"] < dd_trough_price:
            dd_trough = r["date"]
            dd_trough_price = r["close"]

# Capture last drawdown if still in one
if in_drawdown and dd_trough is not None:
    dd_pct = (dd_trough_price / peak_price - 1) * 100
    if dd_pct < -20:
        drawdowns.append({
            "peak_date": peak_dt.strftime("%b %Y"),
            "trough_date": dd_trough.strftime("%b %Y"),
            "drawdown": round(dd_pct, 1),
            "peak_price": round(peak_price, 2),
            "trough_price": round(dd_trough_price, 2),
        })

# ──────────────────────────────────────────────
# 7.  Volume spike analysis (months with avg vol > 2x overall)
# ──────────────────────────────────────────────
overall_avg_vol = avg_daily_vol
vol_spikes = []
for key in sorted(monthly.keys()):
    m_rows = monthly[key]
    m_avg = sum(x["volume"] for x in m_rows) / len(m_rows)
    if m_avg > overall_avg_vol * 2:
        m_close_start = m_rows[0]["close"]
        m_close_end = m_rows[-1]["close"]
        m_ret = (m_close_end / m_close_start - 1) * 100
        vol_spikes.append({
            "month": datetime.strptime(key + "-01", "%Y-%m-%d").strftime("%b %Y"),
            "avg_volume": round(m_avg),
            "price_change": round(m_ret, 1),
            "multiple": round(m_avg / overall_avg_vol, 1),
        })

# Top 10 volume spikes
vol_spikes.sort(key=lambda x: x["avg_volume"], reverse=True)
top_vol_spikes = vol_spikes[:12]

# ──────────────────────────────────────────────
# 8.  Generate HTML
# ──────────────────────────────────────────────

# Prepare annual data for chart
ann_years = [a["year"] for a in annual_perf]
ann_returns = [round(a["return"], 1) for a in annual_perf]
ann_colors = ["#2a9d8f" if r >= 0 else "#e76f51" for r in ann_returns]
ann_volatilities = [round(a["volatility"], 1) for a in annual_perf]

# Volume by year
ann_avg_vols = [round(a["avg_vol"]) for a in annual_perf]

positive_years = sum(1 for a in annual_perf if a["return"] >= 0)
negative_years = len(annual_perf) - positive_years

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nike Inc. (NKE) — Historical Stock Performance Analysis (2000–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-adapter-date-fns@3.0.0/dist/chartjs-adapter-date-fns.bundle.min.js"></script>
