        m_close_end = m_rows[-1]["close"]
        m_ret = (m_close_end / m_close_start - 1) * 100
        vol_spikes.append({
            "month": datetime.strptime(key + "-01", "%Y-%m-%d").strftime("%b %Y"),
            "avg_volume": round(m_avg),
            "price_change": round(m_ret, 1),
            "multiple": round(m_avg / overall_avg_vol, 1),
        })

# Top 10 volume spikes
vol_spikes.sort(key=lambda x: x["avg_volume"], reverse=True)
top_vol_spikes = vol_spikes[:12]

